<script setup lang="ts">
import { useForm } from '@inertiajs/vue3';
import { ref } from 'vue';
import AdminLayout from '../../../Layouts/AdminLayout.vue';
import type { AdminExamAttemptDetailProps } from '../../../types/admin';

const props = defineProps<AdminExamAttemptDetailProps>();
const recovery = useForm<any>({ action: 'expire', reason: '', idempotency_key: crypto.randomUUID() });
const showRecovery = ref(false);

function formatDate(value: string | null): string { return value ? new Date(value).toLocaleString('vi-VN', { dateStyle: 'short', timeStyle: 'short' }) : '—'; }
function submitRecovery(): void { recovery.post(`/admin/exams/attempts/${props.attempt.id}/recover`, { preserveScroll: true, onSuccess: () => { showRecovery.value = false; } }); }
</script>

<template>
    <AdminLayout :breadcrumb="[{ label: 'Admin', href: '/admin' }, { label: 'Exams', href: '/admin/exams' }, { label: 'Attempt timeline' }]">
        <div class="grid gap-6">
            <header class="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><a href="/admin/exams" class="text-sm font-semibold text-brand-700">← Exam operations</a><h1 class="mt-2 text-3xl font-semibold tracking-tight">{{ props.attempt.exam.title }}</h1><p class="mt-2 text-sm text-slate-500">{{ props.attempt.learner.name }} · attempt {{ props.attempt.publicId }}</p></div><span class="rounded-full bg-slate-100 px-3 py-2 text-sm font-semibold">{{ props.attempt.status }}</span></header>
            <section class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><article class="rounded-2xl border border-slate-200 bg-white p-4"><p class="text-xs text-slate-500">Deadline (server)</p><p class="mt-2 font-semibold">{{ formatDate(props.attempt.deadlineAt) }}</p></article><article class="rounded-2xl border border-slate-200 bg-white p-4"><p class="text-xs text-slate-500">Save version</p><p class="mt-2 font-semibold">{{ props.attempt.saveVersion }}</p></article><article class="rounded-2xl border border-slate-200 bg-white p-4"><p class="text-xs text-slate-500">Questions</p><p class="mt-2 font-semibold">{{ props.attempt.questionsCount }}</p></article><article class="rounded-2xl border border-slate-200 bg-white p-4"><p class="text-xs text-slate-500">Exam window</p><p class="mt-2 text-sm font-semibold">{{ formatDate(props.attempt.examWindow.startsAt) }} → {{ formatDate(props.attempt.examWindow.endsAt) }}</p></article></section>
            <section class="grid gap-6 lg:grid-cols-[1fr_20rem]"><article class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><div class="flex items-center justify-between gap-3"><div><h2 class="text-lg font-semibold">Event timeline</h2><p class="text-sm text-slate-500">Metadata đã redacted; không hiển thị answer, IP hoặc user-agent.</p></div><span v-if="props.attempt.issue" class="rounded-full bg-danger-50 px-3 py-1 text-xs font-semibold text-danger-700">{{ props.attempt.issue }}</span></div><ol class="mt-5 grid gap-3"><li v-for="event in props.events" :key="event.id" class="grid gap-2 rounded-xl border border-slate-100 p-4 sm:grid-cols-[10rem_1fr] sm:items-start"><time class="text-xs text-slate-500">{{ formatDate(event.occurredAt) }}</time><div><p class="font-semibold text-slate-800">{{ event.type }}</p><dl v-if="Object.keys(event.metadata).length" class="mt-2 flex flex-wrap gap-2 text-xs text-slate-500"><template v-for="(value, key) in event.metadata" :key="key"><span class="rounded bg-slate-50 px-2 py-1">{{ key }}: {{ value }}</span></template></dl></div></li><li v-if="!props.events.length" class="rounded-xl border border-dashed border-slate-200 p-8 text-center text-sm text-slate-500">Chưa có event.</li></ol></article><aside class="grid content-start gap-4"><article class="rounded-2xl border border-sky-200 bg-sky-50 p-5"><p class="text-xs font-semibold uppercase tracking-wide text-sky-700">AI policy</p><h2 class="mt-2 font-semibold">{{ props.aiPolicy.label }}</h2><p class="mt-2 text-sm text-slate-700">{{ props.aiPolicy.reason }}</p></article><article class="rounded-2xl border border-slate-200 bg-white p-5"><h2 class="font-semibold">Recovery runbook</h2><p class="mt-2 text-sm text-slate-500">Không sửa answer trực tiếp. Chỉ expire attempt quá deadline, yêu cầu reason và idempotency key.</p><button v-if="props.recovery.allowed" type="button" class="mt-4 w-full rounded-xl bg-danger-600 px-4 py-3 text-sm font-semibold text-white" @click="showRecovery = !showRecovery">{{ showRecovery ? 'Đóng recovery' : 'Expire attempt' }}</button><p v-else class="mt-4 rounded-xl bg-slate-50 p-3 text-xs text-slate-600">Recovery chưa được phép: attempt phải đang thi và đã quá deadline theo server time.</p><form v-if="showRecovery" class="mt-4 grid gap-3 border-t border-slate-100 pt-4" @submit.prevent="submitRecovery"><label class="grid gap-1 text-sm font-semibold">Reason<textarea v-model="recovery.reason" required minlength="3" maxlength="500" class="min-h-24 rounded-xl border-slate-200 text-sm font-normal" /></label><p v-if="recovery.errors.reason" class="text-xs text-danger-700">{{ recovery.errors.reason }}</p><button type="submit" class="rounded-xl bg-slate-900 px-4 py-3 text-sm font-semibold text-white disabled:opacity-50" :disabled="recovery.processing">{{ recovery.processing ? 'Đang xử lý…' : 'Xác nhận expire' }}</button></form></article></aside></section>
        </div>
    </AdminLayout>
</template>
